mapper.select:
SELECT COUNT(*)
FROM BALANCE
WHERE USER_SEQ = #{userSeq}

SELECT SEQ AS seq, USER_SEQ AS userSeq, BALANCE AS balance, TOTAL_BALANCE AS totalBalance, OPERATION AS operation, COMMENT AS comment, REG_DATE AS regDate FROM BALANCE WHERE USER_SEQ = #{userSeq} AND OPERATION = 'P'
AND DATE(REG_DATE) >= #{startDate}
AND DATE(REG_DATE) <= #{endDate}
ORDER BY SEQ DESC

SELECT DATE(REG_DATE) AS statDate, OPERATION AS operation, COUNT(*) AS transactionCount, SUM(BALANCE) AS totalAmount FROM BALANCE WHERE 1=1
AND USER_SEQ = #{userSeq}
AND DATE(REG_DATE) >= #{startDate}
AND DATE(REG_DATE) <= #{endDate}
GROUP BY DATE(REG_DATE), OPERATION ORDER BY DATE(REG_DATE) DESC, OPERATION

SELECT DATE_FORMAT(REG_DATE, '%Y-%m') AS statMonth, OPERATION AS operation, COUNT(*) AS transactionCount, SUM(BALANCE) AS totalAmount FROM BALANCE WHERE 1=1
AND USER_SEQ = #{userSeq}
AND DATE(REG_DATE) >= #{startDate}
AND DATE(REG_DATE) <= #{endDate}
GROUP BY DATE_FORMAT(REG_DATE, '%Y-%m'), OPERATION ORDER BY statMonth DESC, OPERATION

SELECT CASE WHEN COMMENT LIKE '%SMS%' THEN 'SMS' WHEN COMMENT LIKE '%LMS%' THEN 'LMS' WHEN COMMENT LIKE '%MMS%' THEN 'MMS' WHEN COMMENT LIKE '%카카오%' OR COMMENT LIKE '%알림톡%' OR COMMENT LIKE '%친구톡%' THEN 'KAKAO' WHEN COMMENT LIKE '%설문%' OR COMMENT LIKE '%survey%' THEN 'SURVEY' WHEN COMMENT LIKE '%QR%' THEN 'QR' WHEN COMMENT LIKE '%충전%' OR OPERATION = 'P' THEN 'CHARGE' WHEN COMMENT LIKE '%환불%' OR OPERATION = 'R' THEN 'REFUND' ELSE 'ETC' END AS serviceType, COUNT(*) AS transactionCount, SUM(BALANCE) AS totalAmount FROM BALANCE WHERE 1=1
AND USER_SEQ = #{userSeq}
AND DATE(REG_DATE) >= #{startDate}
AND DATE(REG_DATE) <= #{endDate}
GROUP BY serviceType ORDER BY totalAmount DESC

SELECT USER_SEQ AS userSeq, OPERATION AS operation, COUNT(*) AS transactionCount, SUM(BALANCE) AS totalAmount FROM BALANCE WHERE 1=1
AND USER_SEQ IN
#{id}
AND DATE(REG_DATE) >= #{startDate}
AND DATE(REG_DATE) <= #{endDate}
GROUP BY USER_SEQ, OPERATION ORDER BY USER_SEQ, OPERATION

SELECT COALESCE(SUM(CASE WHEN OPERATION = 'P' THEN BALANCE ELSE 0 END), 0) AS totalCharge, COALESCE(SUM(CASE WHEN OPERATION = 'M' THEN BALANCE ELSE 0 END), 0) AS totalDeduct, COALESCE(SUM(CASE WHEN OPERATION = 'R' THEN BALANCE ELSE 0 END), 0) AS totalRefund, COUNT(CASE WHEN OPERATION = 'P' THEN 1 END) AS chargeCount, COUNT(CASE WHEN OPERATION = 'M' THEN 1 END) AS deductCount, COUNT(CASE WHEN OPERATION = 'R' THEN 1 END) AS refundCount FROM BALANCE WHERE 1=1
AND USER_SEQ = #{userSeq}
AND DATE(REG_DATE) >= #{startDate}
AND DATE(REG_DATE) <= #{endDate}

SELECT SEQ AS seq, USER_SEQ AS userSeq, BALANCE AS balance, TOTAL_BALANCE AS totalBalance, OPERATION AS operation, COMMENT AS comment, REG_DATE AS regDate, REG_ID AS regId FROM BALANCE WHERE 1=1
AND OPERATION = #{operation}
ORDER BY SEQ DESC LIMIT #{limit}
